{"policy":"permit (
    principal is User,
    action == Action::"approveChange",
    resource is ChangeRequest
)
when {
    (principal.isChangeManager || principal.isCabApprover) &&
    (
        (resource.estimatedCost.lessThan(context.cabSignoffCostThreshold) &&
         principal.grantedChangeAuthorityLevel >= resource.assessedRisk) ||
        (resource.estimatedCost.greaterThanOrEqual(context.cabSignoffCostThreshold) &&
         principal.isCabApprover)
    )
};

forbid (
    principal is User,
    action == Action::"approveChange",
    resource is ChangeRequest
)
when {
    (resource.estimatedCost.lessThan(context.cabSignoffCostThreshold) &&
     resource.assessedRisk > principal.grantedChangeAuthorityLevel) ||
    (resource.estimatedCost.greaterThanOrEqual(context.cabSignoffCostThreshold) &&
     !principal.isCabApprover)
};

permit (
    principal is User,
    action == Action::"implementChange",
    resource is ChangeRequest
)
when {
    principal.isNetworkEngineer &&
    resource.currentStatus == ChangeStatus::"Approved" &&
    (resource.isEmergency ||
     context.currentTime.greaterThanOrEqual(resource.maintenanceWindowStart))
};

forbid (
    principal is User,
    action == Action::"implementChange",
    resource is ChangeRequest
)
when {
    resource.currentStatus != ChangeStatus::"Approved"
};"}
